          searchUtils.WORKFLOW_JOB_INDEX,
          mockStartDate,
          mockEndDate,
          searchUtils.MIN_SCORE,
          searchUtils.MAX_SIZE,
          searchUtils.OLDEST_FIRST,
        ],
      ])
    );

    mock.mockClear();

    // Missing job name
    expect(
      await searchUtils.querySimilarFailures({
        ...query,
        name: "",
      })
    ).toStrictEqual([]);

    // Missing failures
    expect(
      await searchUtils.querySimilarFailures({
        ...query,
        failure_captures: [],
      })
    ).toStrictEqual([]);

    // Check if the workflow name is set
    expect(
      await searchUtils.querySimilarFailures({
        ...query,
        jobName: "job / test",
        name: `pull / job / test`,
      })
    ).toStrictEqual([mockJobData]);
    expect(JSON.stringify(mock.mock.calls)).toEqual(
      JSON.stringify([
        [
          "TESTING",
          query.failure_captures.join(" "),
          "pull",
          "",
          searchUtils.WORKFLOW_JOB_INDEX,
          mockStartDate,
          mockEndDate,
          searchUtils.MIN_SCORE,
          searchUtils.MAX_SIZE,
          searchUtils.OLDEST_FIRST,
        ],
      ])
    );
  });
});

import type { NextApiResponse } from "next";

export type MockApiResponse = NextApiResponse & {
  _status: number;
  _json: any;
  _headers: Record<string, any>;
  _ended: boolean;
};

export function mockRes(): MockApiResponse {
  const res: any = {
    _status: 0,
    _json: null,
    _headers: {},
    _ended: false,
    setHeader(name: string, value: any) {
      res._headers[name] = value;
      return res;
    },
    status(code: number) {
      res._status = code;
      return res;
    },
    json(data: any) {
      res._json = data;
      return res;
    },
    end(data?: any) {
      res._ended = true;
      if (data !== undefined) {
        res._json = data;
      }
      return res;
    },
  };
  return res;
}

import { backfillMissingLog } from "lib/jobUtils";
import * as lambda from "lib/lambda";
import { RecentWorkflowsData } from "lib/types";

const job = { id: 999, conclusion: "failure" } as RecentWorkflowsData;

describe("backfillMissingLog", () => {
  afterEach(() => jest.restoreAllMocks());

  test("queues an upload and reports success", async () => {
    const invoke = jest.spyOn(lambda, "invokeLogUploader").mockResolvedValue();

    await expect(
      backfillMissingLog("pytorch", "executorch", job)
    ).resolves.toBe(true);
    expect(invoke).toHaveBeenCalledWith({
      repo: "pytorch/executorch",
      job_id: 999,
      conclusion: "failure",
    });
  });

  test.each([
    ["credentials are missing", new lambda.MissingAwsCredentialsError()],
    ["the Lambda API is unreachable", new Error("TimeoutError")],
    ["the role cannot invoke", new Error("AccessDeniedException")],
  ])("returns false rather than throwing when %s", async (_label, error) => {
    // Dr.CI calls this mid-comment-render for every failed job with no log. An
    // exception here would take down the whole Dr.CI run over one missing log.
    jest.spyOn(lambda, "invokeLogUploader").mockRejectedValue(error);
    jest.spyOn(console, "error").mockImplementation(() => {});

    await expect(backfillMissingLog("pytorch", "pytorch", job)).resolves.toBe(
      false
    );
  });
});
